import{_ as t,o as r,a as i,ag as o}from"./chunks/framework.Do1Zayaf.js";const p=JSON.parse('{"title":"Roxie CCD Server Logic & Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"aidoc/roxie-kb/server-logic.md","filePath":"aidoc/roxie-kb/server-logic.md","lastUpdated":1779520499000}'),a={name:"aidoc/roxie-kb/server-logic.md"};function n(s,e,c,l,d,u){return r(),i("div",null,e[0]||(e[0]=[o('<h1 id="roxie-ccd-server-logic-architecture" tabindex="-1">Roxie CCD Server Logic &amp; Architecture <a class="header-anchor" href="#roxie-ccd-server-logic-architecture" aria-label="Permalink to &quot;Roxie CCD Server Logic &amp; Architecture&quot;">​</a></h1><h2 id="file-roxie-ccd-ccdserver-cpp" tabindex="-1">File: <code>roxie/ccd/ccdserver.cpp</code> <a class="header-anchor" href="#file-roxie-ccd-ccdserver-cpp" aria-label="Permalink to &quot;File: `roxie/ccd/ccdserver.cpp`&quot;">​</a></h2><p><code>ccdserver.cpp</code> is a colossal file (~26,000 lines) housing the core execution logic for the Roxie query engine on the server side. As the rapid data delivery mechanism for the HPCC platform, Roxie depends on this component to orchestrate distributed operations, fetch data from worker nodes, limit consumption, and coordinate activities.</p><h3 id="core-activity-system" tabindex="-1">Core Activity System <a class="header-anchor" href="#core-activity-system" aria-label="Permalink to &quot;Core Activity System&quot;">​</a></h3><p>The core processing is structured around &quot;Activities&quot;. The <code>CRoxieServerActivity</code> is the predominant building block. Activities read, filter, sort, write, or transform records.</p><ul><li><strong>CRoxieServerActivityFactoryBase</strong>: General factory classes are used inside the execution graph to instantiate these Activities for each specific query upon request.</li><li><strong>CRoxieServerMultiInputFactory</strong> and <strong>CRoxieServerMultiOutputFactory</strong>: Complex queries often require scattering requests or gathering responses, these manage operations requiring multiple inputs or generating multiple outputs.</li></ul><h3 id="concurrency-patterns-concurrency-bottlenecks" tabindex="-1">Concurrency Patterns &amp; Concurrency Bottlenecks <a class="header-anchor" href="#concurrency-patterns-concurrency-bottlenecks" aria-label="Permalink to &quot;Concurrency Patterns &amp; Concurrency Bottlenecks&quot;">​</a></h3><p>Being a high-performance system, several elements exist to handle concurrency and multithreading:</p><ul><li><strong><code>RestartableThread</code></strong> and <strong><code>RecordPullerThread</code></strong>: Often, records are read asynchronously using a producer/consumer or pull model. <code>RecordPullerThread</code> reads ahead in its own thread to minimize I/O stalling while the query executes blockages elsewhere.</li><li><strong><code>CParallelActivityExecutor</code> / <code>CAsyncFor</code></strong>: When multiple paths of the query are independent, parallel execution loops dispatch work items across thread pools.</li><li><strong>Stranded Processing (<code>StrandProcessor</code> / <code>CRoxieServerStrandedActivity</code>)</strong>: Roxie optimizes cache usage and avoids excessive locking and context switching by utilizing &quot;stranded&quot; execution. Different elements or subsets of processing are localized to specific logic strands ensuring temporal locality and minimal lock contention.</li></ul><h3 id="reliability-resiliency" tabindex="-1">Reliability &amp; Resiliency <a class="header-anchor" href="#reliability-resiliency" aria-label="Permalink to &quot;Reliability &amp; Resiliency&quot;">​</a></h3><ol><li><strong>Timeouts and Constraints</strong>: Queries in Roxie must adhere to strict limits. Throwing <code>LimitSkipException</code> and wrapping components inside <code>CWrappedException</code> shows boundary-checking and failover semantics are built deeply into the server activities to prevent run-away queries.</li><li><strong>Dynamic Thread Management</strong>: By dynamically starting and managing operations via customized asynchronous streams (<code>IEngineRowStream</code>), the system aims to restrict resource exhaustion.</li></ol><h3 id="server-to-worker-iterations" tabindex="-1">Server-to-Worker Iterations <a class="header-anchor" href="#server-to-worker-iterations" aria-label="Permalink to &quot;Server-to-Worker Iterations&quot;">​</a></h3><p>Activities often proxy index reads and remote evaluations via <code>udplib</code> and <code>socketutils</code> (not completely handled <em>in</em> this file, but orchestrated by it). Any activity communicating externally requires fine-grained tuning around its blocking nature. Delay execution structures (e.g. <code>CRoxieServerLateStartActivity</code>) postpone heavy lifting until explicitly requested by upstream consumers, which saves cycles on prematurely aborted queries.</p><h3 id="extracted-insights" tabindex="-1">Extracted Insights <a class="header-anchor" href="#extracted-insights" aria-label="Permalink to &quot;Extracted Insights&quot;">​</a></h3><ol><li><strong>Activity Orchestration Inherently Slower if not Batched</strong>: Due to virtual method calls per-row and nested activity hierarchies (e.g. <code>IEngineRowStream</code> <code>nextRow()</code>), deep execution graphs can suffer from instruction cache misses. Vectorized operations and strand batching serve to mitigate this delay.</li><li><strong>Refactoring Recommendation</strong>: This module spans multi-dimensional domains including logging (<code>CRoxieContextLogger</code>), network execution proxying, record pullers, and more. Splitting out logic by execution families (e.g., input vs output vs stranded vs general transforms) would significantly reduce the blast radius for changes targeting only specific execution stages.</li></ol>',15)]))}const g=t(a,[["render",n]]);export{p as __pageData,g as default};
